    return Results.BadRequest(new { error = "Idempotency-Key header is required" });

if (db.IdempotencyKeys.TryGetValue(idempotencyKey, out var cached) &&
    DateTimeOffset.UtcNow < cached.ExpiresAt)
    return Results.Ok(cached.Response);

var txId = Guid.NewGuid().ToString("N")[..16];
